/* Retailer email imports and profile creation, always for one explicit vault. */
(()=>{'use strict';
 const d=document,api=window.desktopAPI?.profileWorkshop;if(!api?.generate)return;
 const retail={target:'Target',walmart:'Walmart',pokemoncenter:'Pokémon Center',costco:'Costco',sams:"Sam’s Club"};
 const modal=d.createElement('div');modal.className='workshopModal';modal.hidden=true;
 modal.innerHTML=`<div class="workshopBox" role="dialog" aria-modal="true" aria-labelledby="emailVaultTitle"><div class="workshopHead"><h2 id="emailVaultTitle">Email Vault &amp; Create Profiles</h2><button type="button" class="btn plain" data-close>X</button></div>
 <div class="workshopForm"><label>Vault<select data-owner></select></label><label>Retailer<select data-retailer>${Object.entries(retail).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label></div>
 <p data-destination></p><p data-counts></p><details open><summary>Import emails</summary><p>Paste one email per line, or import TXT, CSV (email column), or JSON (email strings or objects). Already used emails and duplicates are skipped for this retailer.</p><textarea data-emails rows="5" aria-label="Emails to import" style="width:100%"></textarea><input data-file type="file" accept=".txt,.csv,.json" aria-label="Import email file"><button data-import class="btn secondary" type="button">Import into selected vault</button></details>
 <details open><summary>Create profiles from unused emails</summary><div class="workshopForm"><label>Number of profiles<input data-count type="number" min="1" max="500" value="1"></label><label>Format<select data-format><option value="shikari">Shikari CSV</option><option value="valor">Valor JSON</option></select></label></div><p>Select cards and addresses belonging to this vault.</p><details open><summary>Saved addresses</summary><div data-addresses></div></details><details open><summary>Unused saved cards</summary><div data-cards></div></details><label class="workshopCheck"><input data-reuse type="checkbox"> Distribute selected cards evenly (allow reuse in this batch)</label><label class="workshopCheck"><input data-names type="checkbox" checked> Randomize names; shipping and billing names match</label><button data-generate class="btn primary" type="button">Create profiles in selected vault</button></details><p data-status role="status" aria-live="polite"></p></div>`;
 d.body.append(modal);const $=s=>modal.querySelector('[data-'+s+']');let epoch=0,busy=false;
 const scope=()=>{if(!$('owner').value)throw Error('Select a customer vault.');return $('owner').value==='personal'?{scope:'personal',customerId:null}:{scope:'aco',customerId:$('owner').value.slice(4)};};
 const request=()=>({...scope(),retailer:$('retailer').value});
 const note=s=>{$('status').textContent=s;};
 function pending(on){busy=on;for(const x of modal.querySelectorAll('button,input,select,textarea'))x.disabled=on;}
 async function unlock(p){if(p.scope==='personal'&&!await window.JigPersonalGuard?.ensureUnlocked?.())throw Error('Unlock your private vault first.');}
 function rows(kind,items){$(kind).replaceChildren();for(const item of items){const l=d.createElement('label'),c=d.createElement('input'),t=d.createElement('span');l.className='workshopCheck';c.type='checkbox';c.value=item.id;c.checked=true;t.textContent=kind==='cards'?[item.label,'ending '+item.last4].join(' | '):[item.label,item.address1,item.address2,item.city,item.zip].filter(Boolean).join(' | ');l.append(c,t);$(kind).append(l);}if(!items.length)$(kind).textContent='No saved '+kind+' available. Add them using Cards & Addresses Vault for this owner.';}
 async function refresh(){if(!$('owner').value){$('addresses').replaceChildren();$('cards').replaceChildren();$('counts').textContent='';$('destination').textContent='Select a customer vault.';note('Choose a customer before importing or creating profiles.');return;}const ticket=++epoch,p=request();$('addresses').replaceChildren();$('cards').replaceChildren();$('counts').textContent='';$('destination').textContent='Destination: '+$('owner').selectedOptions[0].textContent+' / '+retail[p.retailer];pending(true);
  try{await unlock(p);const [emails,assets]=await Promise.all([api.emails(p),api.assets(p)]);if(ticket!==epoch||modal.hidden)return;
   $('counts').textContent=emails.emails.filter(x=>x.status==='available').length+' unused emails | '+emails.emails.filter(x=>x.status==='used').length+' used emails';
   rows('addresses',assets.addresses);rows('cards',assets.cards.filter(x=>x.unused));note('Profiles use emails, cards and addresses from the displayed vault only.');
  }catch(e){if(ticket===epoch)note(e.message);}finally{if(ticket===epoch)pending(false);}
 }
 function values(text,name='emails.txt'){
  if(text.length>2000000)throw Error('Import a file smaller than 2 MB.');
  if(/\.json$/i.test(name)){const v=JSON.parse(text),a=Array.isArray(v)?v:Array.isArray(v.emails)?v.emails:Object.values(v);return a.map(x=>typeof x==='string'?x:x?.email||'');}
  const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());
  // CSV parsing includes quoted columns; an email header selects the column.
  const parse=line=>{const out=[];let value='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){value+='"';i++;}else q=!q;}else if(!q&&/[,;\t]/.test(c)){out.push(value.trim());value='';}else value+=c;}out.push(value.trim());return out;};
  const head=lines.length?parse(lines[0]):[],col=head.findIndex(x=>/^(email|account.?email|login.?email)$/i.test(x));
  return lines.slice(col<0?0:1).map(l=>parse(l)[Math.max(col,0)]);
 }
 $('file').addEventListener('change',async()=>{const file=$('file').files[0];if(!file)return;const ticket=epoch;try{if(file.size>2000000)throw Error('Import a file smaller than 2 MB.');const text=await file.text();if(ticket!==epoch||modal.hidden)return;$('emails').value=values(text,file.name).join('\n');note('File ready. Review the destination and click Import.');}catch(e){note(e.message);}});
 for(const key of ['owner','retailer'])$(key).addEventListener('change',()=>{$('emails').value='';$('file').value='';$('format').value=$('retailer').value==='target'?'shikari':'valor';void refresh();});
 $('import').addEventListener('click',async()=>{if(busy)return;if(!$('owner').value){note('Select a customer vault.');return;}const p=request(),ticket=epoch;pending(true);try{await unlock(p);const r=await api.importEmails({...p,emails:values($('emails').value)});if(ticket!==epoch)return;$('emails').value='';$('file').value='';await refresh();note('Imported '+r.added+' emails. Skipped '+r.skipped+' duplicates/already used; '+r.invalid+' invalid entries.');}catch(e){note(e.message);}finally{pending(false);}});
 $('generate').addEventListener('click',async()=>{if(busy)return;if(!$('owner').value){note('Select a customer vault.');return;}const p=request(),ticket=epoch;pending(true);try{await unlock(p);const selected=kind=>[...$(kind).querySelectorAll('input:checked')].map(x=>x.value);const r=await api.generate({...p,count:Number($('count').value),format:$('format').value,addressIds:selected('addresses'),cardIds:selected('cards'),allowCardReuse:$('reuse').checked,randomNames:$('names').checked});if(ticket!==epoch)return;await refresh();void window.ACOProfileBank?.refresh?.();note('Created '+r.created+' profiles in '+$('owner').selectedOptions[0].textContent+' / '+retail[p.retailer]+'. Open Profiles in Cards & Addresses Vault to review and export.');}catch(e){note(e.message);}finally{pending(false);}});
 function close(force=false){if(busy&&!force)return;epoch++;modal.hidden=true;$('emails').value='';$('file').value='';$('addresses').replaceChildren();$('cards').replaceChildren();}
 $('close').addEventListener('click',()=>close());d.addEventListener('jigstudio:personal-locked',()=>{if($('owner').value==='personal'){close(true);note('Private vault locked.');}});modal.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,input,select,textarea,summary')].filter(x=>!x.disabled&&x.getClientRects().length),a=nodes[0],b=nodes.at(-1);if(e.shiftKey&&d.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&d.activeElement===b){e.preventDefault();a.focus();}}});
 async function open(){if(busy)return;$('owner').replaceChildren();const option=(value,label)=>{const o=d.createElement('option');o.value=value;o.textContent=label;$('owner').append(o);};option('personal','My private vault');for(const c of window.JigWebsiteCustomers?.list?.()||[])option('aco:'+c.id,c.name||c.id);
  const bank=window.ACOProfileBank?.context?.(),active=window.JigStudioLocalImport?.workspaceScope?.();if(active==='aco'){if(!bank?.customerId){option('','Choose customer');$('owner').value='';}else $('owner').value='aco:'+bank.customerId;}
  modal.style.zIndex='12000';modal.hidden=false;await refresh();$('close').focus();}
 const button=d.createElement('button');button.type='button';button.className='btn secondary';button.textContent='Email Vault / Create Profiles';button.addEventListener('click',()=>void open());d.getElementById('profileWorkshop')?.querySelector('.workshopHead .buttons')?.append(button);
})();
